import { readFileSync, writeFileSync } from 'node:fs';

const files = [
  'README.md',
  'package.json',
  'src/content/level1.js',
  'src/core/CharacterController.js',
  'src/core/Collision.js',
  'src/core/Engine.js',
  'src/core/Entity.js',
  'src/core/EventBus.js',
  'src/core/InputState.js',
  'src/core/Physics.js',
  'src/core/Replay.js',
  'src/demo/runDemo.js',
  'src/smb/createSMBLikeRuleSet.js',
  'src/world/buildWorldFromAscii.js',
  'test/engine.test.js'
];

const sections = files.map((file) => {
  const content = readFileSync(file, 'utf8').trimEnd();
  return [
    '/* ============================================================================',
    ` * FILE: ${file}`,
    ' * ========================================================================== */',
    content,
    ''
  ].join('\n');
});

const header = [
  '/*',
  ' * SMB-like engine source bundle',
  ' * Generated by: node tools/make-single-file-bundle.mjs',
  ` * Date (UTC): ${new Date().toISOString()}`,
  ' */',
  ''
].join('\n');

writeFileSync('dist/engine-all-in-one.txt', header + sections.join('\n'), 'utf8');
console.log('Wrote dist/engine-all-in-one.txt');
